// Setup
let canvasWidth, canvasHeight;
let camera, scene, renderer;

function setup() {
  canvasWidth = window.innerWidth;
  canvasHeight = window.innerHeight;
  createScene();
}

function createScene() {
  scene = new THREE.Scene();
  camera = new THREE.PerspectiveCamera(75, canvasWidth / canvasHeight, 0.1, 1000);
  camera.position.z = 5;
  renderer = new THREE.WebGLRenderer({
    canvas: document.getElementById('canvas'),
    antialias: true
  });
  renderer.setSize(canvasWidth, canvasHeight);
  renderer.setClearColor(0xffffff, 1);
}

// Main draw loop
function draw() {
  requestAnimationFrame(draw);
  renderer.render(scene, camera);
}

// Heart fractal function
function heartFractal(x, y, size, depth) {
  if (depth === 0) return;
  size /= 2;
  const h = size * 0.3;
  beginShape();
  vertex(x, y);
  bevelVertex(x + size, y);
  bevelVertex(x + size, y + h);
  bevelVertex(x + size * 0.7, y + h * 2);
  bevelVertex(x, y + h * 2);
  endShape();
  heartFractal(x, y, size, depth - 1);
  heartFractal(x + size, y, size, depth - 1);
}

// Render the heart fractal
function renderHeart() {
  const heartGeom = new THREE.Geometry();
  const heartMat = new THREE.MeshBasicMaterial({ color: 0xFF0000, opacity: 0.5, transparent: true });
  const heartMesh = new THREE.Mesh(heartGeom, heartMat);
  scene.add(heartMesh);
  heartFractal(-1.5, -1.5, 3, 5);
  // Animate the heart
  requestAnimationFrame(() => {
    heartMesh.rotation.y += 0.01;
  });
}

setup();
draw();
renderHeart();
```
