import React, { useState, useEffect } from 'react';

const Autocomplete = ({ options, onSelect, placeholder }) => {
  const [value, setValue] = useState('');
  const [suggestions, setSuggestions] = useState([]);
  const [activeItem, setActiveItem] = useState(-1);

  useEffect(() => {
    const handleInput = (event) => {
      const userInput = event.target.value;
      const suggestions = options.filter((option) => option.toLowerCase().includes(userInput.toLowerCase()));
      setSuggestions(suggestions);
      setActiveItem(-1);
    };

    document.addEventListener('input', handleInput);

    return () => {
      document.removeEventListener('input', handleInput);
    };
  }, [options]);

  const handleSelect = (index) => {
    onSelect(options[index]);
    setValue('');
  };

  const handleKeyDown = (event) => {
    if (event.key === 'Enter') {
      handleSelect(activeItem);
    } else if (event.key === 'ArrowUp') {
      setActiveItem(Math.max(activeItem - 1, 0));
    } else if (event.key === 'ArrowDown') {
      setActiveItem(Math.min(activeItem + 1, suggestions.length - 1));
    }
  };

  return (
    <div>
      <input
        type="search"
        value={value}
        onChange={(event) => setValue(event.target.value)}
        placeholder={placeholder}
        onKeyDown={handleKeyDown}
      />
      {suggestions.length > 0 && (
        <ul>
          {suggestions.map((suggestion, index) => (
            <li
              key={index}
              className={activeItem === index ? 'active' : ''}
              onClick={() => handleSelect(index)}
            >
              {suggestion}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default Autocomplete;
```
