    {
        using (var listener = new HttpListener())
        {
            listener.Prefixes.Add("http://localhost:8080/");
            listener.Start();

            while (true)
            {
                ThreadPool.QueueUserWorkItem((context) =>
                {
                    var ctx = (HttpListenerContext)context;
                    var request = ctx.Request;
                    var response = ctx.Response;

                    // Traitement de la requête
                    if (request.Url.AbsolutePath == "/hello")
                    {
                        string responseContent = "Hello";
                        byte[] buffer = System.Text.Encoding.UTF8.GetBytes(responseContent);
                        response.ContentLength64 = buffer.Length;
                        Stream output = response.OutputStream;
                        output.Write(buffer, 0, buffer.Length);
                        output.Close();
                    }
                    else
                    {
                        // traitement des erreurs 404
                        using (var writer = new StreamWriter(response.OutputStream))
                        {
                            writer.WriteLine("Erreur 404 : page non trouvée");
                        }
                    }
                }, listener.GetContext());
            }
        }
    }
}
```
Ce code crée un objet `HttpListener` et configure le prefix (`UrlPrefixes.Add`) pour répondre à toutes les requêtes HTTP sur le port 8080.

